const units:readonly B1Unit[]=[...baseUnits,...B2_EXPANSION];
const rowIndex:Record<NewLanguageId,2|3|4>={fr:2,de:3,es:4};
const msgIndex:Record<NewLanguageId,4|5|6>={fr:4,de:5,es:6};
export function b2Units(id:NewLanguageId):TopicIntro[]{return units.map(u=>({slug:u.slug,title:u.title,subtitle:'تمرین ارتباط پیشرفته B2',situation:u.situation,teachingFa:`${u.notes[id]} آوانویسی فارسی تقریبی است.`,rows:u.rows.map(r=>{const [text,pronunciation,word]=r[rowIndex[id]];return [text,r[0],pronunciation,word,r[1]] as SentenceSeed;})}));}
export function b2UnitSkills(id:NewLanguageId):Record<string,readonly A1SkillTask[]>{return Object.fromEntries(units.map(u=>[`${id}-b2-${u.slug}`,u.messages.map((m,i)=>{const choices=[m[2],m[3]];choices.splice(i+1,0,m[1]);return {kind:i===0?'listening':'reading',passage:m[msgIndex[id]],promptFa:m[0],choices,correctIndex:i+1,explanationFa:`بر اساس پیام، پاسخ «${m[1]}» است.`};})]));}
export function b2GrammarPatterns(id:NewLanguageId,lessonId:string):A2GrammarPattern[]{const prefix=`${id}-b2-`;if(!lessonId.startsWith(prefix))return [];return (units.find(u=>u.slug===lessonId.slice(prefix.length))?.patterns[id]??[]).map(([form,explanationFa,example])=>({form,explanationFa,example}));}
export function countB2GrammarPatterns(id:NewLanguageId,ids:readonly string[]):number{return new Set(ids.flatMap(lessonId=>b2GrammarPatterns(id,lessonId).map(p=>p.form))).size;}
export const B2_UNIT_SLUGS=units.map(u=>u.slug);
